<script lang="ts">
 import {DateTime} from 'luxon';
 import {automaticGanttPeriod,ganttPeriodBounds,clipGanttTicket,ganttTicks,type GanttPeriod} from '$lib/project-gantt-period';
 import {localization} from '$lib/localization';
 import {day,ticketOrder,type Project,type Ticket,type Relation,type Person} from '$lib/projects';
 import DragHandleIcon from '../DragHandleIcon.svelte';
 import StatusNotice from '../StatusNotice.svelte';
 let {tickets,projects,relations,onopen,mode='project',period=null,widthStorageKey}:{tickets:Ticket[];projects:Project[];relations:Relation[];mode?:string;period?:GanttPeriod|null;widthStorageKey:string;onopen:(t:Ticket,el:HTMLElement|null)=>void}=$props();
 let dismissed=$state(''),collapsed=$state<string[]>([]);let previousMode='project';
 $effect(()=>{if(mode!==previousMode){collapsed=[];previousMode=mode;}});
 const defaultTicketWidth=260,minTicketWidth=120,maxTicketWidth=2000;
 const clampWidth=(value:number)=>Math.max(minTicketWidth,Math.min(maxTicketWidth,Math.round(value)));
 let ticketWidth=$state(defaultTicketWidth),resizing=$state<{pointerId:number;x:number;width:number}|null>(null);
 $effect(()=>{const key=widthStorageKey;if(typeof window==='undefined')return;let width=defaultTicketWidth;try{const saved=localStorage.getItem(key);const value=saved===null?NaN:Number(saved);if(Number.isInteger(value)&&value>=minTicketWidth&&value<=maxTicketWidth)width=value;}catch{/* optional storage */}ticketWidth=width;});
 function rememberWidth(){try{localStorage.setItem(widthStorageKey,String(ticketWidth));}catch{/* resizing still works without storage */}}
 function resetWidth(){ticketWidth=defaultTicketWidth;rememberWidth();}
 function beginResize(event:PointerEvent){if(event.button!==0||resizing)return;event.preventDefault();const handle=event.currentTarget as HTMLElement;handle.focus({preventScroll:true});handle.setPointerCapture(event.pointerId);resizing={pointerId:event.pointerId,x:event.clientX,width:ticketWidth};}
 function moveResize(event:PointerEvent){if(resizing?.pointerId===event.pointerId)ticketWidth=clampWidth(resizing.width+event.clientX-resizing.x);}
 function finishResize(event:PointerEvent,cancel=false){if(resizing?.pointerId!==event.pointerId)return;if(cancel)ticketWidth=resizing.width;else rememberWidth();resizing=null;const handle=event.currentTarget as HTMLElement;if(handle.hasPointerCapture(event.pointerId))handle.releasePointerCapture(event.pointerId);handle.blur();}
 function resizeKey(event:KeyboardEvent){
  if(event.key==='Escape'&&resizing){event.preventDefault();ticketWidth=resizing.width;const {pointerId}=resizing;resizing=null;const handle=event.currentTarget as HTMLElement;if(handle.hasPointerCapture(pointerId))handle.releasePointerCapture(pointerId);handle.blur();return;}
  if(resizing)return;
  if(event.key==='ArrowLeft'||event.key==='ArrowRight'){event.preventDefault();ticketWidth=clampWidth(ticketWidth+(event.key==='ArrowRight'?1:-1)*(event.shiftKey?50:10));}
  else if(event.key==='Home'||event.key==='End'){event.preventDefault();ticketWidth=event.key==='Home'?minTicketWidth:maxTicketWidth;}
  else return;
  rememberWidth();
 }
 let ja=$derived($localization.displayLanguage==='ja');const tr=(j:string,e:string)=>ja?j:e;
 const pname=(t:Ticket)=>{const p=projects.find(p=>p.id===t.projectId);return p?.name??'';};
 const assignee=(t:Ticket&{assignee?:Person|null})=>{if(t.assigneeId===null)return tr('担当者未設定','Unassigned');const e=t.assignee??projects.find(p=>p.id===t.projectId)?.members.find(m=>m.employeeId===t.assigneeId)?.employee;return e?e.lastName+' '+e.firstName:tr('担当者情報なし','Assignee unavailable');};
 const sorted=(items:Ticket[])=>[...items].sort((a,b)=>(day(a.startsOn)||'9999').localeCompare(day(b.startsOn)||'9999')||a.id-b.id);
 type Row={key:string;label?:string;ticket?:Ticket;depth?:number};
 let rows=$derived.by(():Row[]=>{const rows:Row[]=[];if(mode==='none')return sorted(tickets).map(ticket=>({key:String(ticket.id),ticket,depth:0}));
 const groups=new Map<string,Ticket[]>();for(const t of tickets){const key=mode==='project'?String(t.projectId):String(t.assigneeId??'none');groups.set(key,[...(groups.get(key)??[]),t]);}
 for(const [key,items] of [...groups].sort((a,b)=>(mode==='project'?pname(a[1][0]):assignee(a[1][0])).localeCompare(mode==='project'?pname(b[1][0]):assignee(b[1][0])))){
 const group=mode+':'+key;rows.push({key:group,label:(mode==='project'?pname(items[0]):assignee(items[0]))+' ('+items.length+')'});
 if(!collapsed.includes(group))for(const {ticket,depth} of mode==='project'?ticketOrder(items):sorted(items).map(ticket=>({ticket,depth:0})))rows.push({key:String(ticket.id),ticket,depth});
 }return rows;});
 let activePeriod=$derived(period??automaticGanttPeriod(tickets,DateTime.now().setZone($localization.timeZone).toISODate()!));
 let bounds=$derived(ganttPeriodBounds(activePeriod));
 let ticks=$derived(ganttTicks(activePeriod));
 const x=(date:string)=>(Date.parse(day(date)+'T00:00:00Z')-bounds.start)/bounds.duration*1000;
 const start=(t:Ticket)=>x(t.startsOn??t.dueOn!);const end=(t:Ticket)=>x(t.dueOn??t.startsOn!)+1000/bounds.days;
 const clampX=(value:number)=>Math.max(0,Math.min(1000,value));
 let lines=$derived(relations.filter(r=>r.kind==='finish_start').flatMap(r=>{const a=rows.findIndex(row=>row.ticket?.id===r.fromId),b=rows.findIndex(row=>row.ticket?.id===r.toId);const from=rows[a]?.ticket,to=rows[b]?.ticket;if(!from?.dueOn||!to?.startsOn)return [];const x1=end(from),x2=start(to);return Math.max(x1,x2)<0||Math.min(x1,x2)>1000?[]:[{key:r.id,x1:clampX(x1),x2:clampX(x2),arrow:x2>=0&&x2<1000,y1:a*48+24,y2:b*48+24,label:pname(from)+' '+from.code+' → '+to.code}];}));
 let warnings=$derived(relations.filter(r=>r.kind==='finish_start').flatMap(r=>{const a=tickets.find(t=>t.id===r.fromId),b=tickets.find(t=>t.id===r.toId);return a?.dueOn&&b?.startsOn&&day(b.startsOn)<=day(a.dueOn)?[pname(a)+' '+a.code+' → '+b.code]:[];}));
</script>
{#if warnings.length&&dismissed!==warnings.join()}<StatusNotice onDismiss={()=>dismissed=warnings.join()} tone="warning" message={tr('依存関係と日程が矛盾しています：','Dependency dates conflict: ')+warnings.join(', ')}/>{/if}
<!-- svelte-ignore a11y_no_noninteractive_tabindex (keyboard users must be able to scroll the content) -->
<div class="gantt" class:resizing={resizing!==null} style:--ticket-column-width={ticketWidth+'px'} role="region" aria-label={tr('横断ガントチャート','Cross-project Gantt chart')} tabindex="0"><div class="gantt-inner">
 <!-- svelte-ignore a11y_no_noninteractive_element_interactions (a focusable ARIA separator supports pointer and keyboard resizing) -->
 <div class="column-resizer" role="separator" aria-orientation="vertical" aria-label={tr('チケット列の幅を変更','Resize ticket column')} aria-valuenow={ticketWidth} aria-valuemin={minTicketWidth} aria-valuemax={maxTicketWidth} aria-valuetext={ticketWidth+'px'} aria-controls="gantt-ticket-rows" tabindex="0" title={tr('ドラッグまたは左右キーで幅を変更。ダブルクリックで初期幅に戻す。','Drag or use arrow keys to resize. Double-click to restore the default width.')} onpointerdown={beginResize} onpointermove={moveResize} onpointerup={e=>finishResize(e)} onpointercancel={e=>finishResize(e,true)} onlostpointercapture={event=>{if(resizing?.pointerId===event.pointerId){rememberWidth();resizing=null;(event.currentTarget as HTMLElement).blur();}}} onkeydown={resizeKey} ondblclick={resetWidth}>{#each Array.from({length:Math.max(1,Math.ceil((rows.length*48+44)/240))},(_,i)=>i) as index}<span class="resize-grip" style:top={index*240+6+'px'} aria-hidden="true"><DragHandleIcon size={16}/></span>{/each}</div>
 <div class="gantt-head"><div class="ticket-heading"><span>{tr('チケット','Ticket')}</span>
</div><div class="time-scale">{#each ticks as tick}<span style:left={tick.part*100+'%'}>{tick.date}</span>{/each}</div></div>
 <div class="gantt-body" id="gantt-ticket-rows">
 {#each rows as row (row.key)}<div class="gantt-row" class:group={!!row.label}>
 {#if row.label}<button class="group-toggle" style:grid-column="1 / -1" style:white-space="nowrap" style:text-overflow="ellipsis" aria-expanded={!collapsed.includes(row.key)} onclick={()=>{collapsed=collapsed.includes(row.key)?collapsed.filter(k=>k!==row.key):[...collapsed,row.key];}}>{collapsed.includes(row.key)?'▸':'▾'} {row.label}</button>
 {:else if row.ticket}{@const t=row.ticket}{@const visibleBar=clipGanttTicket(t,activePeriod)}<button class="ticket-label" class:with-project={mode!=='project'} style:padding-left={(row.depth??0)*12+8+'px'} onclick={e=>onopen(t,e.currentTarget)}>{#if mode!=='project'}<small>{pname(t)}</small>{/if}<span class="ticket-title" title={t.code+' '+t.title}>{t.code} {t.title}</span></button><div class="timeline">{#if visibleBar}<button class="bar" class:milestone={projects.find(p=>p.id===t.projectId)?.types.some(type=>type.id===t.typeId&&type.milestone)} style:left={visibleBar.left+'%'} style:width={visibleBar.width+'%'} aria-label={`${pname(t)} ${t.code} ${t.title}: ${[day(t.startsOn),day(t.dueOn)].filter(Boolean).join(' → ')}`} onclick={e=>onopen(t,e.currentTarget)}>{visibleBar.from}{#if visibleBar.from!==visibleBar.to} → {visibleBar.to}{/if}</button>{/if}</div>{/if}
 </div>{/each}
 {#if rows.length}<svg class="dependency-lines" viewBox={`0 0 1000 ${rows.length*48}`} preserveAspectRatio="none" role="img" aria-label={tr('依存関係','Dependencies')}>{#each lines as line (line.key)}<path d={`M ${line.x1} ${line.y1} H ${Math.min(1000,line.x1+8)} V ${line.y2} H ${line.x2}`}><title>{line.label}</title></path>{#if line.arrow}<path d={`M ${line.x2-4} ${line.y2-4} L ${line.x2} ${line.y2} L ${line.x2-4} ${line.y2+4}`}/>{/if}{/each}</svg>{/if}
 </div></div></div>
<style>.time-scale{position:relative;height:20px}.time-scale span{position:absolute;transform:translateX(-50%);white-space:nowrap;font-size:var(--font-size-support)}.time-scale span:first-child{transform:none;margin-left:14px}.time-scale span:last-child:not(:first-child){transform:translateX(-100%)}.gantt{overflow:auto;max-width:100%}.gantt-inner{position:relative;min-width:calc(var(--ticket-column-width) + 640px)}.gantt-body{position:relative}.gantt-head,.gantt-row{display:grid;grid-template-columns:var(--ticket-column-width) minmax(640px,1fr)}.gantt-row{height:48px;border-bottom:1px solid var(--border)}.gantt-head{font-size:var(--font-size-support);color:var(--muted);align-items:center;min-height:44px}.ticket-heading{position:relative;box-sizing:border-box;height:44px;display:flex;align-items:center;padding:0 8px;min-width:0}.column-resizer{position:absolute;left:calc(var(--ticket-column-width) - 22px);top:0;bottom:0;width:44px;z-index:2;cursor:col-resize;touch-action:none}.column-resizer::after{content:"";position:absolute;left:21px;top:0;bottom:0;width:1px;background:var(--border)}.resize-grip{position:absolute;left:13px;z-index:1;display:grid;place-items:center;box-sizing:border-box;width:18px;height:28px;border:1px solid var(--border);border-radius:var(--sph-radius-3px,3px);background:var(--surface);color:var(--muted);pointer-events:none}.column-resizer:hover::after,.resizing .column-resizer::after{width:2px;background:var(--muted)}.column-resizer:hover .resize-grip,.resizing .resize-grip{background:var(--surface-hover);border-color:var(--muted)}.column-resizer:focus-visible{outline:0}.column-resizer:focus-visible .resize-grip{outline:2px solid var(--muted);outline-offset:2px}.resizing{user-select:none;cursor:col-resize}.group{background:var(--surface-hover)}button{font:inherit;border:0;background:transparent;color:var(--text);text-align:left;cursor:pointer}.ticket-label{overflow:hidden;font-size:var(--font-size-body);line-height:1.3}.ticket-title{display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;line-clamp:2;overflow:hidden}.with-project .ticket-title{-webkit-line-clamp:1;line-clamp:1}.ticket-label small{font-size:var(--font-size-support);display:block;color:var(--muted);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.group-toggle{font-weight:600;overflow:hidden}.timeline{position:relative;overflow:hidden;background:repeating-linear-gradient(to right,transparent 0,transparent calc(10% - 1px),var(--border) calc(10% - 1px),var(--border) 10%)}.bar{position:absolute;top:10px;height:28px;background:var(--action-primary);color:white;border-radius:4px;font-size:var(--font-size-support);white-space:nowrap;overflow:hidden;z-index:1}.bar.milestone{width:18px!important;height:18px;top:14px;transform:rotate(45deg);font-size:0}.dependency-lines{position:absolute;left:var(--ticket-column-width);top:0;width:calc(100% - var(--ticket-column-width));height:100%;pointer-events:none;overflow:hidden}.dependency-lines path{fill:none;stroke:var(--text-secondary,var(--muted));stroke-width:1.3;vector-effect:non-scaling-stroke}</style>
